export const meta = {
  name: 'slice2-design',
  description: 'Design telelean slice 2 (the review list / edit sessions engine): 3 read-only designers, a synthesizer writing docs/slice2-plan.md, a critic',
  phases: [{ title: 'Design' }, { title: 'Synthesize' }, { title: 'Critique' }],
}

const R = '/home/zhengyew/telelean'
const S = '/tmp/claude-1000/-home-zhengyew-telelean/20626c17-0334-4498-ad86-9dc24b7010ed/scratchpad'
const SPEC = R + '/verbatim_prompt_log/bundle_21/user_requested_documents/01_spec_v4.md'
const AP = R + '/verbatim_prompt_log/bundle_21/user_requested_documents/02_autopilot_decisions.md'
const P1 = R + '/docs/slice1-plan.md'
const SAFETY = `SAFETY AND RESOURCE RULES (mandatory): READ-ONLY for the repository except where your task says you write ONE file. Never change git state (read-only git is fine). No network, no installs, no Claude, no builds, no tests, no Lean (other agents are building in the same tree right now; do not run anything heavy). Do not touch packages/extension/dist or out. Use reading tools and read-only shell commands only.`

const CONTEXT = `Context: telelean (${R}) is a VS Code extension (TypeScript monorepo: packages/core, runner, extension, webview) that shows a user's beliefs as cards backed by Lean 4 files; Claude formalises and proves through the user's Claude Code CLI; a non-LLM gate decides what counts. The user approved spec v4.1 (${SPEC}) and put the build on autopilot; every decision taken without them is logged in ${AP}. Slice 1 (the new board, arrows, glows/bands, Formalize for dependencies on today's single-target all-or-nothing review, read-only board during a run) is nearly done: see ${P1} (sections 1-5 and the section 8 change log written by every builder) and the code. Sub-slice 1e (Formalize, the Context Menu replacing the tray, the gate's B.2 no-hidden-edges rule) is being built right now: read ${S}/briefs/1e.md to know what it adds.

SLICE 2 = "the review list" (★D8 (a) item 2 in the spec's Part 2): real edit sessions. It covers spec v4.1 §7 ES-1..ES-9 as far as sessions started by Formalize for dependencies go (several targets per Formalize, sources first, every step re-judging every inference: ES-2, RV-11; ES-4 failures/rollback/Cancel/Retry; ES-5; ES-6 reload; ES-7 base never moves, with a live drift notice), §9 REVIEW STAGE RV-1..RV-13 (items: Add, Add premise, Add arrow/Remove arrow, Change, Formalize, Delete, Vocabulary (N), Result, Proof broken; the list = status table; statuses incl. "to be redone"; item dependencies RV-5; meaning before proof RV-6 with the v4.1 hidden set; RV-7 own-Accept classes recomputed on every judged state; groups RV-8; mid-stage Formalize RV-9; stage report RV-10; Submit review RV-12), §10 DECLINE OPTIONS (DO-0 arrow items plain decline, DO-1 Reject, DO-3 Shaky; DO-2 Transform waits for slice 4 — say how the UI behaves until then), §11 ENDING EN-1..EN-4 (Apply with the final check and the backstop of §14.5 / Appendix B, Exit, keep ticks only as far as freezes exist — FROZEN is slice 3, so in slice 2 Accept does not freeze: a later step may change an accepted item, which then returns to "in review", marked "updated"), §12 UNDO UN-4..UN-6 (the session stack), the session bar CM-6, Appendix B's per-inference checks (B.1 permitted sets with E(T), B.2, B.3, B.4, backstop) for multi-target sessions, and arrow items (Claude may now propose arrows into targets, each an item). NOT in slice 2: FROZEN (slice 3), the transform window (slice 4), references (slice 5). Constraints: no real Claude in tests (FakeBackend / recorded streams), the user's installed extension runs from packages/extension/dist (never build there except at verified slice ends), RAM may be tight (tests single-worker under caps), the user reviews design later: log choices.`

const DESIGN_SCHEMA = {
  type: 'object',
  properties: {
    summary: { type: 'string' },
    current_state: { type: 'string', description: 'what exists today in your area, with file:line references' },
    design: { type: 'string', description: 'the proposed design in detail: data model, contracts (TypeScript types), algorithms, protocol messages, state machine, persistence' },
    sub_slices: { type: 'array', items: { type: 'object', properties: { id: { type: 'string' }, scope: { type: 'string' }, files: { type: 'array', items: { type: 'string' } }, tests: { type: 'string' }, risk: { type: 'string' } }, required: ['id', 'scope', 'files', 'tests'] } },
    open_questions: { type: 'array', items: { type: 'string', description: 'a decision needed, with your recommended answer' } },
    safety_notes: { type: 'array', items: { type: 'string' } },
  },
  required: ['summary', 'current_state', 'design', 'sub_slices', 'open_questions', 'safety_notes'],
}

phase('Design')
const lenses = [
  { key: 'engine', text: `YOUR AREA: THE SESSION ENGINE (runner + core). How a session, its stages and steps, and its items are represented and persisted (today: runs with rounds, proposals, the shadow git, run.json; read packages/runner/src/run/manager.ts, run/types.ts, proposal/*, shadow/*, core/src/run.ts, core/src/proposal/*, core/src/gate/*). Design: item computation between the session base (never moves) and the working copy, stable item ids across stages (an updated proposal updates its item in place), statuses and their transitions (in review / accepted / declined with option / to be redone; "updated"), Submit review → structured feedback to Claude (what was accepted, rejected, Shaky, to redo) and the next step; several targets proved sources first in one session, each target an inference with its own question and permitted set (B.1 incl. E(T) arrow items and sources proved earlier in the session), RV-11 re-judging every inference after every step, ES-4 rollback that never undoes the user's decisions, Cancel/Retry step, ES-6 reload, ES-7 live drift detection (a watcher; Apply disabled while files differ), Apply = applying exactly the accepted items to the base with every check re-run on the final state plus the backstop (Appendix B), Exit. Say how the existing all-or-nothing Accept path is reused or replaced, and how the gate rules change (per-inference checks; accepted content vs baseline; new-axiom; markup rule for Claude-proposed arrows).` },
  { key: 'review-ui', text: `YOUR AREA: THE REVIEW UI (webview + protocol). Today's review is a stepper (read packages/webview/src/run/*, model/run.ts, state/store.ts run parts, core/src/protocol.ts run messages, the 1c/1d board code for the Proposed view overlay). Design: the review list as the status table (RV-2: grouped by card, arrow items under their target, badges belief / changes what is proved / depends on N, counts, filter, keyboard Back/Next ↑/↓, A accepts, D declines, Accept & next, the detail pane with sentence above Lean, Fully explicit toggle, what the Lean uses), Result items neutral until revealed (RV-6 hidden set incl. other cards' derived data in the Proposed view), Show result, the stage report above the list (RV-10), group Accept/Decline with RV-7 own-Accept items skipped and listed (RV-8), decline options (DO-0 plain for arrow items; DO-1 Reject with "Rejected in this session"; DO-3 Shaky; DO-2 Transform disabled until slice 4 with its reason), the session bar (CM-6: Submit review, Exit session, Cancel step/Resume, Raw Lean diff, Current|Proposed), the end confirmation (EN-2: changes as links, final check, failures, Back to review; Exit's discard summary), the session Undo stack (UN-4..UN-6: what is a step, sealing at every Claude step, discarded at the end, never touching files), the "Your files changed since the session started" notice. Specify the protocol messages (host↔webview) with validators, and how the Proposed view of the board (canvas, bands, glows) shows proposed arrows (translucent with +/−, BD-5) and hides results.` },
  { key: 'safety', text: `YOUR AREA: SAFETY, CLASSIFICATION AND CHECKS (core gate + Lean facts). Design precisely: RV-5 item dependencies (I's Lean, as Lean sees it after elaboration, mentions something J adds or changes — how to compute "mentions" from the facts: elaborated value/type constants (1d's valueConsts and the type's constants), plus Result→arrow and arrow→card-added dependencies and the cycle-avoidance dependency); RV-7 classification by effect in Lean (belief: adds an axiom card / formalises or changes an axiom / adds or changes any Lean axiom / adds a definition, instance or coercion in the elaborated closure of a card's statement / meaning-changed items; changes what is proved: changes an existing statement or proof, the statement a Result proves, the sentence of a formalised card, any Add arrow into a proposition), recomputed on every judged state (S-6); the Apply backstop (Appendix B: every new or changed Lean axiom except shape-passing vocabulary, every definition/instance/coercion in a statement's elaborated closure, every existing name whose kind/type/value changed must belong to an individually accepted item; every arrow yours or accepted; B.2 for every proposition whose proof or Dependencies changed; acyclicity; held/frozen parts deferred to slice 3); per-inference permitted sets in a multi-target session (B.1) and how accepted-but-not-applied content counts (RV-11's "a proof you accepted earlier counts like one of your own for later inferences"); the hidden-result computation for RV-6 (what derived data depends on a hidden Result); and the test strategy (FakeBackend scenarios that attempt each cheat from Part 3: S1, S4, S5, S6, S14, S15, S17, S18, S22). Read core/src/gate/*, core/src/project/*, runner/src/gate/*, and the spec Part 3 + Appendix B.` },
]
const designs = await parallel(lenses.map((l) => () => agent(`${SAFETY}\n\n${CONTEXT}\n\n${l.text}\n\nBe concrete: name files, functions, types, messages; give TypeScript type sketches for new contracts; reuse what exists. Propose sub-slices for your area (each buildable and testable on its own, in dependency order). List open questions with your recommended answer (the integrator decides on autopilot). Note every safety property your design must preserve and how it is tested.`, { label: `design:${l.key}`, phase: 'Design', schema: DESIGN_SCHEMA })))

phase('Synthesize')
const plan = await agent(`${SAFETY} EXCEPTION: you write exactly ONE new file, ${R}/docs/slice2-plan.md (create it; nothing else).\n\n${CONTEXT}\n\nThree designers each produced a design for one area of slice 2 (JSON below). Write the slice-2 implementation plan as ${R}/docs/slice2-plan.md, in the style and structure of ${P1} (read it first): purpose and scope (what is in and out of slice 2), rules for builders (same as slice 1's section 0), the order of sub-slices (each ending compiling with unit tests passing and a patch saved; at most ~8 sub-slices; each small enough for one builder agent), the contracts (types, protocol messages, persistence formats, gate rules) decided precisely, the design of the session engine, the review UI and the checks, the test plan (incl. FakeBackend cheat scenarios), decisions you had to take (each marked "AUTOPILOT DECISION:" with the alternative, so the integrator can log it), and a change log section. Resolve conflicts between the designs explicitly. Keep the spec's clause IDs as references. After writing the file, return a short summary: the sub-slice list (id + one line), the autopilot decisions (one line each), and anything you could not resolve.\n\n=== DESIGNS ===\n${JSON.stringify(designs.filter(Boolean), null, 1)}`, { label: 'synthesize:plan', phase: 'Synthesize' })

phase('Critique')
const CRIT = { type: 'object', properties: { summary: { type: 'string' }, findings: { type: 'array', items: { type: 'object', properties: { id: { type: 'string' }, severity: { type: 'string', enum: ['blocker', 'major', 'minor', 'nit'] }, where: { type: 'string' }, problem: { type: 'string' }, fix: { type: 'string' } }, required: ['id', 'severity', 'where', 'problem', 'fix'] } } }, required: ['summary', 'findings'] }
const critique = await agent(`${SAFETY}\n\n${CONTEXT}\n\nCritique the slice-2 plan just written at ${R}/docs/slice2-plan.md, adversarially, on two lenses: (1) SOUNDNESS — could the planned engine let anything become assumed without the user's individual Accept, show a result before the meaning check, apply a state no check judged, let a proof rest on something its question does not allow, or lose the user's decisions on rollback/reload? (2) IMPLEMENTABILITY — are the contracts complete and consistent with the current code (read it), are the sub-slices buildable one at a time by one agent each, is anything missing from the spec's slice-2 scope (compare with the clauses listed in the context)? Report findings with concrete fixes to the plan text.`, { label: 'critique:plan', phase: 'Critique', schema: CRIT })

return { designs, plan, critique }
